    // Generic Folder Accordion for Hierarchical Sidebar Navigation
    function toggleFolderAccordion(containerId, chevronId) {
      const container = document.getElementById(containerId);
      const chevron = document.getElementById(chevronId);
      if (!container) return;

      const isHidden = container.classList.contains('hidden');
      if (isHidden) {
        // Expand this folder
        container.classList.remove('hidden');
        if (chevron) {
          chevron.classList.add('rotate-90');
          chevron.classList.remove('rotate-180');
        }
      } else {
        // Collapse this folder
        container.classList.add('hidden');
        if (chevron) {
          chevron.classList.remove('rotate-90');
          chevron.classList.remove('rotate-180');
        }

        // Auto close all lower / child folders recursively
        const childContainers = container.querySelectorAll('[id$="Cont"], [id$="FolderCont"]');
        childContainers.forEach(child => {
          child.classList.add('hidden');
        });

        // Reset all descendant chevrons to closed (pointing right)
        const childChevrons = container.querySelectorAll('[id$="Chev"], [id$="FolderChev"]');
        childChevrons.forEach(ch => {
          ch.classList.remove('rotate-90');
          ch.classList.remove('rotate-180');
        });
      }
    }
