    function navigateView(viewId) {
      if (!viewId) viewId = 'flowchart';

      // Normalize merged views
      if (viewId === 'catalog') {
        viewId = 'spreadsheet';
      } else if (viewId === 'compliance') {
        viewId = 'dashboard';
        setTimeout(() => switchDashboardTab('compliance'), 15);
      } else if (viewId === 'homePdProgramView' || viewId === 'workbench') {
        renderProgramOverview(currentSelectedProgram || 'BSCpE');
        return;
      }

      // Auto-close mobile sidebar if open on smaller screens
      if (typeof isMobileSidebarOpen !== 'undefined' && isMobileSidebarOpen && window.innerWidth < 768) {
        if (typeof toggleMobileSidebar === 'function') {
          toggleMobileSidebar();
        }
      }

      // Hide all application views
      const allViews = ['home', 'curriculum-home', 'flowchart', 'catalog', 'obe', 'dashboard', 'compliance', 'delegation', 'audit', 'registrar', 'syllabus', 'course', 'spreadsheet'];
      
      allViews.forEach(v => {
        const el = document.getElementById('view-' + v);
        const nav = document.getElementById('nav-' + v);
        if (el) el.classList.add('hidden');
        if (nav) {
          nav.classList.remove('active-rams-btn', 'bg-[#002855]', 'bg-[#E5A823]', 'text-white', 'text-slate-950');
          nav.classList.add('text-slate-300');
        }
      });

      // Clear left panel regdoc buttons if not in registrar view
      if (viewId !== 'registrar') {
        for (let i = 1; i <= 7; i++) {
          const navBtn = document.getElementById(`nav-regdoc-${i}`);
          if (navBtn) {
            navBtn.classList.remove('active-rams-btn', 'bg-[#002855]', 'text-white', 'border-l-4', 'border-[#E5A823]', 'bg-slate-800');
            navBtn.classList.add('text-slate-300');
            const badge = navBtn.querySelector('.reg-doc-badge');
            if (badge) {
              badge.classList.remove('bg-amber-400/20', 'text-amber-300', 'border-amber-400/40');
              badge.classList.add('bg-slate-800', 'text-slate-400', 'border-slate-700');
            }
          }
        }
      }

      // Reveal target view
      const targetView = document.getElementById('view-' + viewId);

      if (targetView) {
        targetView.classList.remove('hidden');
        if (viewId === 'home' && typeof renderHomepageForRole === 'function') {
          // Keep active tier view visible inside view-home
          const adminView = document.getElementById('homeAdminInstitutionalView');
          const exdView = document.getElementById('homeExdProgramsView');
          const pdView = document.getElementById('homePdProgramView');
          const facView = document.getElementById('homeFacultyWorkerView');
          const anyVisible = (adminView && !adminView.classList.contains('hidden')) ||
                             (exdView && !exdView.classList.contains('hidden')) ||
                             (pdView && !pdView.classList.contains('hidden')) ||
                             (facView && !facView.classList.contains('hidden'));
          if (!anyVisible) {
            renderHomepageForRole(currentActiveRole || 'admin');
          }
        }
      }

      // Update Path Bar indicator
      const topPill = document.getElementById('topBarPathPill');
      if (topPill) {
        if (viewId === 'home') topPill.innerText = 'Schools';
        else if (viewId === 'curriculum-home') topPill.innerText = 'Schools > SoE > BSCpE > Curriculum Management';
        else if (viewId === 'flowchart') topPill.innerText = 'Schools > SoE > BSCpE > Flowchart';
        else if (viewId === 'spreadsheet') topPill.innerText = 'Schools > SoE > BSCpE > Curriculum Spreadsheet';
        else if (viewId === 'dashboard') topPill.innerText = 'Schools > SoE > BSCpE > Curriculum Dashboard';
        else if (viewId === 'obe') topPill.innerText = 'Schools > SoE > BSCpE > OBE Map';
        else if (viewId === 'syllabus') topPill.innerText = 'Schools > SoE > BSCpE > Syllabus Management';
        else if (viewId === 'course') topPill.innerText = 'Schools > SoE > BSCpE > Course Management';
        else topPill.innerText = 'Schools > ' + viewId.toUpperCase();
      }

      if (viewId !== 'home' && !inSelectProgram) {
        recordNavigationStep({
          type: 'view',
          targetView: viewId,
          pathText: topPill ? topPill.innerText : `Schools > ${viewId.toUpperCase()}`
        });
      }

      // Safe view-specific trigger hooks
      if (viewId === 'flowchart') {
        if (typeof renderFlowchartDiagram === 'function') renderFlowchartDiagram();
        setTimeout(() => { 
          if (typeof drawAllArrows === 'function') drawAllArrows(); 
        }, 80);
      } else if (viewId === 'catalog') {
        if (typeof filterCoursesTable === 'function') filterCoursesTable();
      } else if (viewId === 'obe') {
        if (typeof renderObeMatrix === 'function') renderObeMatrix();
      } else if (viewId === 'registrar') {
        const tab = typeof currentRegistrarTab !== 'undefined' ? currentRegistrarTab : 1;
        if (typeof switchRegistrarDocTab === 'function') {
          switchRegistrarDocTab(tab);
        }
      } else if (viewId === 'spreadsheet') {
        if (typeof renderSpreadsheetGrid === 'function') renderSpreadsheetGrid();
        if (typeof updateSpreadsheetCalculations === 'function') updateSpreadsheetCalculations();
      }

      // Scroll viewport back to top
      window.scrollTo({ top: 0, behavior: 'instant' });
      const mainEl = document.querySelector('main');
      if (mainEl) mainEl.scrollTo({ top: 0, behavior: 'instant' });

      // Sync left sidebar to reflect the newly active view.
      // selectProgram() already calls this, but navigateView() can also be called
      // directly (e.g. from sidebar buttons like "Management Homepage"), so we
      // ensure the sidebar is always up-to-date regardless of the call path.
      if (currentSelectedProgram && typeof syncSidebarToCurrentPath === 'function') {
        const pInfo = (typeof PROGRAM_TO_SCHOOL_MAP !== 'undefined' && PROGRAM_TO_SCHOOL_MAP[currentSelectedProgram])
          || { schoolId: 'soe' };
        syncSidebarToCurrentPath(pInfo.schoolId, currentSelectedProgram, viewId);
      }
    }

